import{_ as s,o as n,c as e,a0 as l}from"./chunks/framework.DqMqoJl9.js";const u=JSON.parse('{"title":"String.raw()","description":"","frontmatter":{},"headers":[],"relativePath":"jsApi/String/raw.md","filePath":"jsApi/String/raw.md","lastUpdated":1791573371000}'),t={name:"jsApi/String/raw.md"};function r(p,a,o,i,c,d){return n(),e("div",null,[...a[0]||(a[0]=[l(`<p><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/String/raw" target="_blank">原文链接</a><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String/raw" target="_blank">en</a></p><h1 id="string-raw" tabindex="-1">String.raw() <a class="header-anchor" href="#string-raw" aria-label="Permalink to &quot;String.raw()&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>String.raw() 是一个模板字符串的标签函数，它的作用类似于 Python 中的字符串前缀 r 和 C# 中的字符串前缀 @，是用来获取一个模板字符串的原始字面量值的。</p><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">String.</span><span style="color:#6F42C1;">raw</span><span style="color:#24292E;">(callSite, </span><span style="color:#D73A49;">...</span><span style="color:#24292E;">substitutions)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h3><ul><li><code>callSite</code> 一个模板字符串的“调用点对象”</li><li><code>...substitutions</code> 任意个可选的参数，表示任意个内插表达式对应的值</li></ul><h3 id="异常" tabindex="-1">异常 <a class="header-anchor" href="#异常" aria-label="Permalink to &quot;异常&quot;">​</a></h3><p><code>TypeError</code></p><p>如果第一个参数没有传入一个格式良好的调用点对象，则会抛出 TypeError 异常。</p><h2 id="描述" tabindex="-1">描述 <a class="header-anchor" href="#描述" aria-label="Permalink to &quot;描述&quot;">​</a></h2><p>不要被上面复杂的参数要求吓到，因为像所有的标签函数一样，你通常不需要把它看成一个普通函数，你只需要把它放在模板字符串前面 就可以了，而不是在它后面加个括号和一堆参数来调用它，引擎会替你去调用它。</p><p>String.raw() 是唯一一个内置的模板字符串标签函数，因为它太常用了。不过它并没有什么特殊能力，你自己也可以实现一个和它功能一模一样的标签函数。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">String.raw </span><span style="color:#032F62;">\`Hi</span><span style="color:#005CC5;">\\n</span><span style="color:#032F62;">!\`</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#6A737D;">// &quot;Hi\\\\n!&quot;，这里得到的不是 Hi 后面跟个换行符，而是跟着 \\ 和 n 两个字符</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">String.raw </span><span style="color:#032F62;">\`Hi</span><span style="color:#005CC5;">\\u000A</span><span style="color:#032F62;">!\`</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#6A737D;">// &quot;Hi\\\\u000A!&quot;，同上，这里得到的会是 \\、u、0、0、0、A 6个字符，</span></span>
<span class="line"><span style="color:#6A737D;">// 任何类型的转义形式都会失效，保留原样输出，不信你试试.length</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49;">let</span><span style="color:#24292E;"> name </span><span style="color:#D73A49;">=</span><span style="color:#032F62;"> &quot;Bob&quot;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">String.raw </span><span style="color:#032F62;">\`Hi</span><span style="color:#005CC5;">\\n</span><span style="color:#032F62;">\${</span><span style="color:#24292E;">name</span><span style="color:#032F62;">}!\`</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#6A737D;">// &quot;Hi\\\\nBob!&quot;，内插表达式还可以正常运行</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">String.</span><span style="color:#6F42C1;">raw</span><span style="color:#24292E;">({raw: </span><span style="color:#032F62;">&quot;test&quot;</span><span style="color:#24292E;">}, </span><span style="color:#005CC5;">0</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">1</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">2</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">// &quot;t0e1s2t&quot;，我认为你通常不需要把它当成普通函数来调用</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><h2 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Specification</th><th style="text-align:left;">Status</th><th style="text-align:left;">Comment</th></tr></thead><tbody><tr><td style="text-align:left;">ECMAScript 2015 (6th Edition, ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;">Initial definition</td></tr></tbody></table>`,18)])])}const h=s(t,[["render",r]]);export{u as __pageData,h as default};
